	//        "type": "IMMEDIATE_OR_CANCEL",
	//        "side": "SELL",
	//        "transactTime": "1745852205223"
	//    }
	//
	//    unknown endpoint on spot
	//
	//    {
	//         "symbol": "BTCUSDT",
	//         "orderId": "123738410679123456",
	//         "orderListId": -1
	//    }
	//
	// margin: createOrder
	//
	//     {
	//         "symbol": "BTCUSDT",
	//         "orderId": "762634301354414080",
	//         "clientOrderId": null,
	//         "isIsolated": true,
	//         "transactTime": 1661992652132
	//     }
	//
	// spot: cancelOrder, cancelAllOrders
	//
	//     {
	//         "symbol": "BTCUSDT",
	//         "orderId": "133926441921286144",
	//         "price": "30000",
	//         "origQty": "0.0002",
	//         "type": "LIMIT",
	//         "side": "BUY"
	//     }
	//
	// margin: cancelOrder, cancelAllOrders
	//
	//     {
	//         "symbol": "BTCUSDT",
	//         "orderId": "762640232574226432",
	//         "orderListId": "-1",
	//         "clientOrderId": null,
	//         "price": "18000",
	//         "origQty": "0.00147",
	//         "executedQty": "0",
	//         "cummulativeQuoteQty": "0",
	//         "status": "NEW",
	//         "type": "LIMIT",
	//         "side": "BUY",
	//         "isIsolated": true,
	//         "isWorking": true,
	//         "time": 1661994066000,
	//         "updateTime": 1661994066000
	//     }
	//
	// spot: fetchOrder, fetchOpenOrders, fetchOrders
	//
	//     {
	//         "symbol": "BTCUSDT",
	//         "orderId": "133734823834147272",
	//         "orderListId": "-1",
	//         "clientOrderId": null,
	//         "price": "30000",
	//         "origQty": "0.0002",
	//         "executedQty": "0",
	//         "cummulativeQuoteQty": "0",
	//         "status": "CANCELED",
	//         "timeInForce": null,
	//         "type": "LIMIT",
	//         "side": "BUY",
	//         "stopPrice": null,
	//         "icebergQty": null,
	//         "time": "1647667102000",
	//         "updateTime": "1647708567000",
	//         "isWorking": true,
	//         "origQuoteOrderQty": "6"
	//     }
	//
	// margin: fetchOrder, fetchOrders
	//
	//     {
	//         "symbol": "BTCUSDT",
	//         "orderId": "763307297891028992",
	//         "orderListId": "-1",
	//         "clientOrderId": null,
	//         "price": "18000",
	//         "origQty": "0.0014",
	//         "executedQty": "0",
	//         "cummulativeQuoteQty": "0",
	//         "status": "NEW",
	//         "type": "LIMIT",
	//         "side": "BUY",
	//         "isIsolated": true,
	//         "isWorking": true,
	//         "time": 1662153107000,
