	//     }
	//
	// swap
	//
	//     {
	//         "success": true,
	//         "code": 0,
	//         "data": [
	//             {
	//                 "currency": "BSV",
	//                 "positionMargin": 0,
	//                 "availableBalance": 0,
	//                 "cashBalance": 0,
	//                 "frozenBalance": 0,
	//                 "equity": 0,
	//                 "unrealized": 0,
	//                 "bonus": 0
	//             },
	//         ]
	//     }
	//
	// margin
	//
	//     {
	//         "assets": [
	//             {
	//                 "baseAsset": {
	//                     "asset": "BTC",
	//                     "borrowEnabled": true,
	//                     "borrowed": "0",
	//                     "free": "0",
	//                     "interest": "0",
	//                     "locked": "0",
