func (this *Mexc) ParsePosition(position any, optionalArgs ...any) any {
	//
	// fetchPositions
	//
	//     {
	//         "positionId": 1394650,
	//         "symbol": "ETH_USDT",
	//         "positionType": 1,
	//         "openType": 1,
	//         "state": 1,
	//         "holdVol": 1,
	//         "frozenVol": 0,
	//         "closeVol": 0,
	//         "holdAvgPrice": 1217.3,
	//         "openAvgPrice": 1217.3,
	//         "closeAvgPrice": 0,
	//         "liquidatePrice": 1211.2,
	//         "oim": 0.1290338,
	//         "im": 0.1290338,
	//         "holdFee": 0,
	//         "realised": -0.0073,
	//         "leverage": 100,
	//         "createTime": 1609991676000,
	//         "updateTime": 1609991676000,
	//         "autoAddIm": false
	//     }
	//
	// fetchPositionsHistory
	//
	//    {
	//        positionId: '390281084',
	//        symbol: 'RVN_USDT',
	//        positionType: '1',
	//        openType: '2',
	//        state: '3',
	//        holdVol: '0',
	//        frozenVol: '0',
	//        closeVol: '1141',
	//        holdAvgPrice: '0.03491',
	//        holdAvgPriceFullyScale: '0.03491',
	//        openAvgPrice: '0.03491',
	//        openAvgPriceFullyScale: '0.03491',
	//        closeAvgPrice: '0.03494',
	//        liquidatePrice: '0.03433',
	//        oim: '0',
	//        im: '0',
	//        holdFee: '0',
	//        realised: '0.1829',
	//        leverage: '50',
	//        createTime: '1711512408000',
	//        updateTime: '1711512553000',
	//        autoAddIm: false,
	//        version: '4',
	//        profitRatio: '0.0227',
	//        newOpenAvgPrice: '0.03491',
	//        newCloseAvgPrice: '0.03494',
	//        closeProfitLoss: '0.3423',
	//        fee: '0.1593977',
	//        positionShowStatus: 'CLOSED'
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	market = this.SafeMarket(this.SafeString(position, "symbol"), market, nil, "swap")
	var symbol any = GetValue(market, "symbol")
	var contracts any = this.SafeString(position, "holdVol")
	var entryPrice any = this.SafeNumber(position, "openAvgPrice")
	var initialMargin any = this.SafeString(position, "im")
	var rawSide any = this.SafeString(position, "positionType")
	var side any = Ternary(IsTrue((IsEqual(rawSide, "1"))), "long", "short")
	var openType any = this.SafeString(position, "margin_mode")
	var marginType any = Ternary(IsTrue((IsEqual(openType, "1"))), "isolated", "cross")
	var leverage any = this.SafeNumber(position, "leverage")
	var liquidationPrice any = this.SafeNumber(position, "liquidatePrice")
	var timestamp any = this.SafeInteger(position, "updateTime")
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      symbol,
		"contracts":                   this.ParseNumber(contracts),
		"contractSize":                nil,
		"entryPrice":                  entryPrice,
		"collateral":                  nil,
		"side":                        side,
		"unrealizedPnl":               nil,
		"leverage":                    this.ParseNumber(leverage),
		"percentage":                  nil,
		"marginMode":                  marginType,
		"notional":                    nil,
		"markPrice":                   nil,
		"lastPrice":                   nil,
		"liquidationPrice":            liquidationPrice,
		"initialMargin":               this.ParseNumber(initialMargin),
		"initialMarginPercentage":     nil,
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": nil,
		"marginRatio":                 nil,
		"timestamp":                   timestamp,
		"datetime":                    this.Iso8601(timestamp),
		"hedged":                      nil,
		"stopLossPrice":               nil,
		"takeProfitPrice":             nil,
		"lastUpdateTimestamp":         nil,
	})
}

